// An empty blob has no line to cite.
const lines =
  shown.stdout === ''
    ? []
    : (shown.stdout.endsWith('\n') ? shown.stdout.slice(0, -1) : shown.stdout).split('\n');
if (line > lines.length) {
  return `${path}:${String(line)} is past the end of the file (${String(lines.length)} lines)`;
}
